import { createServiceClient } from "@/lib/supabase";

/** ユーザーのBacklog連携設定 */
export type UserBacklogSettings = {
  spaceUrl: string | null;
  apiKey: string | null;
  projectKeys: string[];
};

/**
 * 指定ユーザーのBacklog連携設定をDBから取得する。
 * profiles テーブルから spaceUrl / apiKey を、
 * user_project_keys テーブルからプロジェクトキー一覧を取得する。
 * @param userId - Supabase Auth のユーザーID
 * @returns ユーザーのBacklog連携設定
 */
export async function getUserBacklogSettings(
  userId: string,
): Promise<UserBacklogSettings> {
  const db = createServiceClient();

  const [profileRes, projectKeysRes] = await Promise.all([
    db
      .from("profiles")
      .select("backlog_space_url, backlog_api_key")
      .eq("id", userId)
      .single(),
    db
      .from("user_project_keys")
      .select("project_key")
      .eq("user_id", userId)
      .order("created_at"),
  ]);

  if (profileRes.error) {
    throw new Error(`Failed to fetch profile: ${profileRes.error.message}`);
  }

  return {
    spaceUrl: profileRes.data.backlog_space_url,
    apiKey: profileRes.data.backlog_api_key,
    projectKeys: (projectKeysRes.data ?? []).map((row) => row.project_key),
  };
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createServiceClient } from "@/lib/supabase";

/** PUT リクエストボディの型 */
type SettingsUpdateBody = {
  spaceUrl?: string | null;
  apiKey?: string | null;
  projectKeys?: string[];
};

/**
 * 認証済みユーザーのBacklog連携設定を取得する。
 * profiles から spaceUrl / apiKey を、user_project_keys からプロジェクトキー一覧を返す。
 */
export async function GET() {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const db = createServiceClient();

    const [profileRes, projectKeysRes] = await Promise.all([
      db
        .from("profiles")
        .select("backlog_space_url, backlog_api_key")
        .eq("id", user.id)
        .single(),
      db
        .from("user_project_keys")
        .select("project_key")
        .eq("user_id", user.id)
        .order("created_at"),
    ]);

    if (profileRes.error) {
      throw new Error(`profiles: ${profileRes.error.message}`);
    }

    return NextResponse.json({
      spaceUrl: profileRes.data.backlog_space_url,
      apiKey: profileRes.data.backlog_api_key,
      projectKeys: (projectKeysRes.data ?? []).map((r) => r.project_key),
    });
  } catch (error) {
    console.error("Failed to fetch settings:", error);
    return NextResponse.json(
      { error: "Failed to fetch settings" },
      { status: 500 },
    );
  }
}

/**
 * 認証済みユーザーのBacklog連携設定を更新する。
 * profiles の spaceUrl / apiKey を更新し、
 * user_project_keys は全削除→再挿入で洗い替えする。
 */
export async function PUT(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body: SettingsUpdateBody = await request.json();
    const db = createServiceClient();

    // profiles の更新（spaceUrl / apiKey）
    const updateData: Record<string, string | null> = {};
    if (body.spaceUrl !== undefined) {
      updateData.backlog_space_url = body.spaceUrl;
    }
    if (body.apiKey !== undefined) {
      updateData.backlog_api_key = body.apiKey;
    }

    if (Object.keys(updateData).length > 0) {
      const { error: updateError } = await db
        .from("profiles")
        .update(updateData)
        .eq("id", user.id);
      if (updateError) {
        throw new Error(`profiles update: ${updateError.message}`);
      }
    }

    // user_project_keys の洗い替え（DELETE → INSERT）
    if (body.projectKeys !== undefined) {
      const { error: deleteError } = await db
        .from("user_project_keys")
        .delete()
        .eq("user_id", user.id);
      if (deleteError) {
        throw new Error(`project_keys delete: ${deleteError.message}`);
      }

      if (body.projectKeys.length > 0) {
        const rows = body.projectKeys.map((key) => ({
          user_id: user.id,
          project_key: key,
        }));
        const { error: insertError } = await db
          .from("user_project_keys")
          .insert(rows);
        if (insertError) {
          throw new Error(`project_keys insert: ${insertError.message}`);
        }
      }
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Failed to update settings:", error);
    return NextResponse.json(
      { error: "Failed to update settings" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { Backlog } from "backlog-js";
import { createClient } from "@/lib/supabase/server";

/** リクエストボディの型 */
type FetchProjectsBody = {
  spaceUrl: string;
  apiKey: string;
};

/** レスポンスで返すプロジェクト情報 */
type BacklogProjectInfo = {
  id: number;
  projectKey: string;
  name: string;
};

/**
 * 指定された Backlog スペースURL + APIキーで、
 * そのスペースに存在する全プロジェクト一覧を返す。
 * 設定画面の「同期するプロジェクト」チェックボックスの選択肢生成に使用する。
 */
export async function POST(request: NextRequest) {
  try {
    // 認証チェック
    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body: FetchProjectsBody = await request.json();

    if (!body.spaceUrl || !body.apiKey) {
      return NextResponse.json(
        { error: "spaceUrl and apiKey are required" },
        { status: 400 },
      );
    }

    // スペースURLからホスト名を抽出して Backlog クライアントを生成
    let host: string;
    try {
      host = new URL(body.spaceUrl).hostname;
    } catch {
      return NextResponse.json(
        { error: "Invalid spaceUrl format" },
        { status: 400 },
      );
    }

    const backlog = new Backlog({ host, apiKey: body.apiKey });
    const projects = await backlog.getProjects();

    const result: BacklogProjectInfo[] = projects.map((p) => ({
      id: p.id,
      projectKey: p.projectKey,
      name: p.name,
    }));

    return NextResponse.json({ projects: result });
  } catch (error) {
    console.error("Failed to fetch Backlog projects:", error);
    const message =
      error instanceof Error ? error.message : "Failed to fetch projects";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { Backlog } from "backlog-js";

/**
 * Backlog APIクライアントを生成する。
 * 引数が指定されていればそれを使い、未指定なら環境変数にフォールバックする。
 * @param spaceUrl - BacklogスペースURL（省略時は BACKLOG_SPACE_URL を参照）
 * @param apiKey - Backlog APIキー（省略時は BACKLOG_API_KEY を参照）
 * @returns Backlog APIクライアントインスタンス
 */
export function createBacklogClient(
  spaceUrl?: string,
  apiKey?: string,
): Backlog {
  const resolvedUrl = spaceUrl || process.env.BACKLOG_SPACE_URL;
  const resolvedKey = apiKey || process.env.BACKLOG_API_KEY;

  if (!resolvedUrl || !resolvedKey) {
    throw new Error(
      "Backlog spaceUrl and apiKey are required (via argument or env)",
    );
  }

  const host = new URL(resolvedUrl).hostname;
  return new Backlog({ host, apiKey: resolvedKey });
}

/**
 * BacklogスペースURLからホスト名を取得する。
 * 引数が指定されていればそれを使い、未指定なら環境変数にフォールバックする。
 * @param spaceUrl - BacklogスペースURL（省略時は BACKLOG_SPACE_URL を参照）
 * @returns Backlogのホスト名（例: "example.backlog.com"）
 */
export function getBacklogHost(spaceUrl?: string): string {
  const resolvedUrl = spaceUrl || process.env.BACKLOG_SPACE_URL;
  if (!resolvedUrl) {
    throw new Error("Backlog spaceUrl is required (via argument or env)");
  }
  return new URL(resolvedUrl).hostname;
}

/**
 * 同期対象のプロジェクトキー一覧を取得する。
 * 引数が指定されていればそれを使い、未指定なら環境変数にフォールバックする。
 * @param projectKeys - プロジェクトキー配列（省略時は BACKLOG_PROJECT_KEYS を参照）
 * @returns プロジェクトキーの配列（例: ["PROJ1", "PROJ2"]）
 */
export function getProjectKeys(projectKeys?: string[]): string[] {
  if (projectKeys && projectKeys.length > 0) {
    return projectKeys;
  }
  const keys = process.env.BACKLOG_PROJECT_KEYS;
  if (!keys) throw new Error("Backlog projectKeys are required (via argument or env)");
  return keys.split(",").map((k) => k.trim()).filter(Boolean);
}

